#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[555555];
int f[555555],d[555555];
int dp[555555][22],l[555555];
void dfs(int p,int g,int fa){
	d[p]=g;
	dp[p][0]=fa;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	}
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
		}
	}
}
int lca(int x,int y){
	if(d[x]<d[y]){
		swap(x,y);
	}
	for(int i=20;i>=0;i--){
		if(d[dp[x][i]]>=d[y]){
			x=dp[x][i];
		}
	}
	if(x==y){
		return x;
	}
	for(int i=20;i>=0;i--){
		if(dp[x][i]!=dp[y][i]){
			x=dp[x][i],y=dp[y][i];
		}
	}
	return dp[x][0];
}
int dis(int x,int y){
	return d[x]+d[y]-d[lca(x,y)]*2;
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,q;
	cin>>n>>q;
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfs(1,1,0);
	while(q--){
		int x,y,z;
		cin>>x>>y>>z;
		int a=lca(x,y),b=lca(x,z),c=lca(y,z);
		l[a]++;
		l[b]++;
		l[c]++;
		if(l[a]==1){
			cout<<a<<" "<<dis(x,a)+dis(a,z)+dis(a,y)<<endl;
		}else if(l[b]==1){
			cout<<b<<" "<<dis(x,b)+dis(b,z)+dis(b,y)<<endl;
		}else if(l[c]==1){
			cout<<c<<" "<<dis(x,c)+dis(c,z)+dis(c,y)<<endl;
		}else if(l[a]==3){
			cout<<a<<" "<<dis(x,a)+dis(a,z)+dis(a,y)<<endl;
		}else if(l[b]==3){
			cout<<b<<" "<<dis(x,b)+dis(b,z)+dis(b,y)<<endl;
		}else if(l[c]==3){
			cout<<c<<" "<<dis(x,c)+dis(c,z)+dis(c,y)<<endl;
		}
		l[a]=0;
		l[b]=0;
		l[c]=0;
	}
    return 0;
}
